Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to translate:
<original_code>
#include <bits/stdc++.h>
using namespace std;

#define LL long long
#define ULL unsigned LL
#define PII pair<int,int>
#define PB push_back
#define MP make_pair
#define INF 1000000000
#define MOD 1000000007

int distArr[15][15][15][15];
int flowCap[400][400];
char scienceGrid[20][20];
char reactionGrid[20][20];
int dirX[] = {1, 0, -1, 0};
int dirY[] = {0, 1, 0, -1};
int currentIteration = 3;
int visitedNodes[400];

int nSize, maxTime;
int findAugment(int cnode, int dest, int bneck) {
    if (cnode == dest) return bneck;
    if (visitedNodes[cnode] == currentIteration) return 0;
    visitedNodes[cnode] = currentIteration;
    for (int i = 0; i <= dest; i++) {
        if (flowCap[cnode][i] > 0) {
            int pushedFlow = findAugment(i, dest, min(bneck, flowCap[cnode][i]));
            if (pushedFlow > 0) {
                flowCap[cnode][i] -= pushedFlow;
                flowCap[i][cnode] += pushedFlow;
                return pushedFlow;
            }
        }
    }
    return 0;
}

int nodeNumber(int x, int y) {
    return (x - 1) * nSize + y - 1;
}

int reachMap[13][13], tempReachMap[13][13];

void spread(int val) {
    for (int i = 1; i <= nSize; i++)
        for (int j = 1; j <= nSize; j++)
            tempReachMap[i][j] = reachMap[i][j];

    for (int i = 1; i <= nSize; i++) {
        for (int j = 1; j <= nSize; j++) {
            if (tempReachMap[i][j] == val) {
                for (int d = 0; d < 4; d++) {
                    int ni = i + dirX[d], nj = j + dirY[d];
                    if (ni > 0 && nj > 0 && ni <= nSize && nj <= nSize && reachMap[ni][nj] < val && scienceGrid[ni][nj] != 'Y') {
                        reachMap[ni][nj] = val;
                    }
                }
            }
        }
    }
}

bool checkReach(int sx, int sy, int tx, int ty, int ix, int iy) {
    memset(reachMap, 0, sizeof(reachMap));
    reachMap[sx][sy] = 1;
    reachMap[ix][iy] = 2;
    for (int i = 0; i < 100; i++) {
        spread(1);
        if (reachMap[tx][ty] == 1) return true;
        spread(2);
        if (reachMap[tx][ty] == 2) return false;
    }
    return false;
}

int main() {
    int infX, infY;
    memset(distArr, 1, sizeof(distArr));
    cin >> nSize >> maxTime;
    for (int i = 1; i <= nSize; i++) {
        scanf(" %s", scienceGrid[i] + 1);
        for (int j = 1; j <= nSize; j++) {
            distArr[i][j][i][j] = 0;
            if (scienceGrid[i][j] == 'Z') {
                infX = i; infY = j;
            }
        }
    }
    for (int i = 1; i <= nSize; i++) {
        scanf(" %s", reactionGrid[i] + 1);
    }
    for (int i = 1; i <= nSize; i++) {
        for (int j = 1; j <= nSize; j++) {
            for (int d = 0; d < 4; d++) {
                int ni = i + dirX[d], nj = j + dirY[d];
                if (ni > 0 && ni <= nSize && nj > 0 && nj <= nSize) {
                    if (scienceGrid[i][j] != 'Y' && scienceGrid[ni][nj] != 'Y') {
                        distArr[i][j][ni][nj] = 1;
                    }
                }
            }
        }
    }
    for (int ki = 1; ki <= nSize; ki++) {
        for (int kj = 1; kj <= nSize; kj++) {
            for (int ii = 1; ii <= nSize; ii++) {
                for (int ij = 1; ij <= nSize; ij++) {
                    for (int ji = 1; ji <= nSize; ji++) {
                        for (int jj = 1; jj <= nSize; jj++) {
                            distArr[ii][ij][ji][jj] = min(
                                distArr[ii][ij][ji][jj],
                                distArr[ii][ij][ki][kj] + distArr[ki][kj][ji][jj]
                            );
                        }
                    }
                }
            }
        }
    }
    int srcNode = nSize * nSize * 2 + 1;
    int sinkNode = nSize * nSize * 2 + 2;
    for (int i = 1; i <= nSize; i++) {
        for (int j = 1; j <= nSize; j++) {
            if (isdigit(scienceGrid[i][j])) {
                flowCap[srcNode][nodeNumber(i, j)] = scien[i][j] - '0';
            }
            if (isdigit(reactionGrid[i][j])) {
                flowCap[nSize * nSize + nodeNumber(i, j)][sinkNode] = reac[i][j] - '0';
            }
            if (isdigit(scienceGrid[i][j])) {
                for (int ki = 1; ki <= nSize; ki++) {
                    for (int kj = 1; kj <= nSize; kj++) {
                        if (scien[i][j] > '0' && reac[ki][kj] > '0') {
                            if (isdigit(reac[ki][kj]) && distArr[i][j][ki][kj] <= maxTime && checkReach(i, j, ki, kj, infX, infY)) {
                                flowCap[nodeNumber(i, j)][nSize * nSize + nodeNumber(ki, kj)] = 1000;
                            }
                        }
                    }
                }
            }
        }
    }
    int totalFlow = 0, flowVal;
    while ((flowVal = findAugment(srcNode, sinkNode, 1000)) > 0) {
        totalFlow += flowVal;
        currentIteration++;
    }
    cout << totalFlow << endl;
    return 0;
}
